quiz.answer:
const lines = require("fs").readFileSync(0, "utf8").split("\n").map((s) => s.trim()).filter((s) => s !== "");

// 1 行 = "名前 到着時刻 所要時間"(単位はミリ秒、到着時刻の早い順に並んでいる)
const events = lines.map((line) => {
  const [name, arrive, cost] = line.split(" ");
  return { name, arrive: Number(arrive), cost: Number(cost) };
});

let now = 0;
let maxWait = 0;
for (const ev of events) {
  const start = Math.max(now, ev.arrive);
  const end = start + ev.cost;
  maxWait = Math.max(maxWait, start - ev.arrive);
  console.log(`${ev.name} ${start} ${end}`);
  now = end;
}
console.log(`max_wait ${maxWait}`);
